COLUNAS_DADOS = [
    'exercicio_decreto',
    'decreto_numero',
    'data_elaboracao',
    'orgao_elaboracao',
    'link_decreto',
    'complemento_informacoes',
    'processo_sei',
]

CAMPOS_BUSCA = (
    'exercicio_decreto',
    'decreto_numero',
    'data_elaboracao',
    'assunto_decreto',
    'orgao_elaboracao',
    'processo_sei',
    'link_decreto',
)


def texto_limpo(valor):
    """Converte valores vazios/nulos em texto e remove espaços externos."""
    if valor is None:
        return ''
    try:
        if pd.isna(valor):
            return ''
    except (TypeError, ValueError):
        pass
    return str(valor).strip()


def normalizar_ano(valor):
    """Evita apresentar anos numéricos como 2026.0."""
    ano = texto_limpo(valor)
    if re.fullmatch(r'\d{4}\.0+', ano):
        return ano.split('.', 1)[0]
    return ano


def normalizar_numero(valor):
    """Remove o sufixo decimal .0 de números inteiros vindos da planilha/banco."""
    numero = texto_limpo(valor)
    if re.fullmatch(r'\d+\.0+', numero):
        return numero.split('.', 1)[0]
    return numero


def formatar_data(valor):
    data = texto_limpo(valor)
    if not data:
        return ''
    if re.fullmatch(r'\d{4}-\d{2}-\d{2}', data):
        convertida = pd.to_datetime(data, format='%Y-%m-%d', errors='coerce')
    else:
        convertida = pd.to_datetime(data, dayfirst=True, errors='coerce')
    if pd.isna(convertida):
        return data
    return convertida.strftime('%d/%m/%Y')


def normalizar_registros(registros):
    """Normaliza campos sem sobrescrever o número de decreto já fornecido."""
    normalizados = []
    for registro in registros:
        linha = dict(registro)
        nomes_colunas = {normalizar_cabecalho(chave): chave for chave in linha}
        sinonimos = {
            'exercicio_decreto': ('exercicio decreto', 'exercicio', 'ano'),
            'decreto_numero': ('decreto numero', 'decreto g', 'decreto', 'numero do decreto'),
            'data_elaboracao': ('data elaboracao', 'data'),
            'orgao_elaboracao': ('orgao elaboracao', 'elaboracao', 'orgao'),
            'processo_sei': ('processo sei', 'sei'),
            'link_decreto': ('link do decreto', 'link decreto', 'link'),
            'complemento_informacoes': ('complemento informacoes', 'complemento'),
            'assunto_decreto': ('assunto decreto', 'assunto'),
            'source_key': ('source key', 'chave origem', 'chave original'),
        }
        for campo, alternativas in sinonimos.items():
            if texto_limpo(linha.get(campo, '')):
                continue
            for alternativa in alternativas:
                chave = nomes_colunas.get(alternativa)
                if chave is not None and texto_limpo(linha.get(chave, '')):
                    linha[campo] = linha[chave]
                    break
            if not texto_limpo(linha.get(campo, '')) and campo == 'complemento_informacoes':
                for nome_normalizado, chave in nomes_colunas.items():
                    if nome_normalizado.startswith('complemento ') and texto_limpo(linha.get(chave, '')):
                        linha[campo] = linha[chave]
                        break

        ano_original = texto_limpo(linha.get('exercicio_decreto', ''))
        numero_original = texto_limpo(linha.get('decreto_numero', ''))

        # Compatibilidade com planilhas antigas que juntavam ano e número
        # na primeira coluna (por exemplo, 2026105). 2026.0 não é dividido.
        if not numero_original and re.fullmatch(r'\d{5,}', ano_original):
            ano_original, numero_original = ano_original[:4], ano_original[4:]

        linha['exercicio_decreto'] = normalizar_ano(ano_original)
        linha['decreto_numero'] = normalizar_numero(numero_original)
        linha['data_elaboracao'] = formatar_data(linha.get('data_elaboracao', ''))
        linha['assunto_decreto'] = texto_limpo(linha.get('assunto_decreto', ''))
        linha['source_key'] = texto_limpo(linha.get('source_key', ''))
        if not linha['assunto_decreto']:
            complemento = texto_limpo(linha.get('complemento_informacoes', ''))
            if complemento.startswith('ASSUNTO: '):
                linha['assunto_decreto'] = complemento.removeprefix('ASSUNTO: ').strip()

        for campo in COLUNAS_DADOS:
            linha.setdefault(campo, '')
            if campo not in ('exercicio_decreto', 'decreto_numero', 'data_elaboracao'):
                linha[campo] = texto_limpo(linha.get(campo, ''))

        linha['_search_text'] = ' '.join(
            texto_limpo(linha.get(campo, '')) for campo in CAMPOS_BUSCA
        ).casefold()
        # Chave única da interface, independente de ano/número repetidos.
        linha['_row_key'] = uuid.uuid4().hex
        normalizados.append(linha)
    return normalizados


def normalizar_cabecalho(valor):
    sem_acento = unicodedata.normalize('NFKD', str(valor))
    sem_acento = ''.join(c for c in sem_acento if not unicodedata.combining(c))
    return re.sub(r'[^a-z0-9]+', ' ', sem_acento.lower()).strip()


def carregar_planilha():
    """Lê a planilha pelo nome dos cabeçalhos, não pela posição das colunas."""
    df = pd.read_csv(URL_PLANILHA, dtype=str)
    cabecalhos = {normalizar_cabecalho(coluna): coluna for coluna in df.columns}

    def encontrar_coluna(*nomes, inicio=None):
        for nome in nomes:
            chave = normalizar_cabecalho(nome)
            if chave in cabecalhos:
                return cabecalhos[chave]
        if inicio:
            chave_inicio = normalizar_cabecalho(inicio)
            for chave, coluna in cabecalhos.items():
                if chave.startswith(chave_inicio):
                    return coluna
        return None

    fontes = {
        'exercicio_decreto': encontrar_coluna('Exercicio', 'Exercício', 'Ano'),
        'decreto_numero': encontrar_coluna('Decreto G', 'Decreto Numero', 'Número do Decreto G'),
        'data_elaboracao': encontrar_coluna('Data', 'Data Elaboracao'),
        'orgao_elaboracao': encontrar_coluna('Elaboracao', 'Orgao Elaboracao'),
        'processo_sei': encontrar_coluna('Processo SEI'),
        'link_decreto': encontrar_coluna('Link do Decreto', 'Link Decreto'),
        'complemento_informacoes': encontrar_coluna(inicio='Complemento'),
    }

    resultado = pd.DataFrame(index=df.index)
    for campo, coluna in fontes.items():
        resultado[campo] = df[coluna] if coluna else ''
    registros = normalizar_registros(resultado.to_dict('records'))
    return [
        registro for registro in registros
        if registro['exercicio_decreto'] and registro['decreto_numero']
    ]


def carregar_banco():
    if not DATABASE_URL:
        return []
    try:
        engine = create_engine(DATABASE_URL)
        df = pd.read_sql('SELECT * FROM decretos', engine)
        return normalizar_registros(df.to_dict('records')) if not df.empty else []
    except Exception as e:
        print(f'Erro ao ler do Neon: {e}')
        return []


def salvar_no_banco(registro, source_key):
    """Cria as colunas canônicas que faltam e insere/atualiza por chave estável."""
    engine = create_engine(DATABASE_URL)
    campos = [
        'exercicio_decreto',
        'decreto_numero',
        'data_elaboracao',
        'orgao_elaboracao',
        'processo_sei',
        'complemento_informacoes',
        'link_decreto',
        'source_key',
    ]
    valores = {
        campo: texto_limpo(registro.get(campo, '')) or None
        for campo in campos
    }
    data_sql = pd.to_datetime(registro.get('data_elaboracao', ''), dayfirst=True, errors='coerce')
    valores['data_elaboracao'] = None if pd.isna(data_sql) else data_sql.strftime('%Y-%m-%d')
    valores['source_key'] = source_key

    with engine.begin() as conexao:
        conexao.execute(text('''
            CREATE TABLE IF NOT EXISTS decretos (
                exercicio_decreto TEXT,
                decreto_numero TEXT,
                data_elaboracao TEXT,
                orgao_elaboracao TEXT,
                processo_sei TEXT,
                complemento_informacoes TEXT,
                link_decreto TEXT,
                source_key TEXT
            )
        '''))
        nomes_existentes = {coluna['name'] for coluna in inspect(conexao).get_columns('decretos')}
        for campo in campos:
            if campo not in nomes_existentes:
                conexao.execute(text(f'ALTER TABLE decretos ADD COLUMN {campo} TEXT'))
            else:
                # Bancos antigos podem ter sido criados com VARCHAR(100),
                # causando erro ao salvar assuntos ou textos mais longos.
                conexao.execute(text(f'ALTER TABLE decretos ALTER COLUMN {campo} TYPE TEXT'))

    tabela_db = Table('decretos', MetaData(), autoload_with=engine)
    sinonimos_db = {
        'exercicio_decreto': {'exercicio decreto', 'exercicio', 'ano'},
        'decreto_numero': {'decreto numero', 'decreto g', 'decreto', 'numero do decreto'},
        'data_elaboracao': {'data elaboracao', 'data'},
        'orgao_elaboracao': {'orgao elaboracao', 'elaboracao', 'orgao'},
        'processo_sei': {'processo sei', 'sei'},
        'complemento_informacoes': {'complemento informacoes', 'complemento'},
        'link_decreto': {'link do decreto', 'link decreto', 'link'},
        'source_key': {'source key', 'chave origem', 'chave original'},
    }
    valores_coluna = {}
    for coluna in tabela_db.columns:
        nome = normalizar_cabecalho(coluna.name)
        for campo, sinonimos in sinonimos_db.items():
            if nome in sinonimos or (campo == 'complemento_informacoes' and nome.startswith('complemento')):
                valor = valores[campo]
                if campo == 'data_elaboracao' and valor:
                    try:
                        valor = pd.to_datetime(valor, errors='coerce').date()
                    except (AttributeError, TypeError, ValueError):
                        pass
                valores_coluna[coluna.name] = valor
                break

    with engine.begin() as conexao:
        atualizacao = conexao.execute(
            tabela_db.update()
            .where(tabela_db.c.source_key == source_key)
            .values(**valores_coluna)
        )
        if atualizacao.rowcount == 0:
            conexao.execute(tabela_db.insert().values(**valores_coluna))


def aplicar_assuntos_e_links(registros):
    """Aplica assunto e link individual, usando ano+número como chave."""
    try:
        conteudo_mapa = gzip.decompress(base64.b64decode(DECRETO_MAPA_GZIP_B64))
        df = pd.read_csv(io.BytesIO(conteudo_mapa), dtype=str).fillna('')
        mapa = {
            (normalizar_ano(linha['exercicio_decreto']), normalizar_numero(linha['decreto_numero'])):
                (texto_limpo(linha['assunto_decreto']), texto_limpo(linha['link_decreto']))
            for _, linha in df.iterrows()
        }
    except Exception as e:
        print(f'Erro ao carregar assuntos/links individuais: {e}')
        mapa = {}

    for registro in registros:
        if registro.get('source_key'):
            # Um registro editado/cadastrado no Neon tem precedência sobre o mapa
            # incorporado, inclusive quando o usuário esvazia um campo.
            continue
        chave = (
            normalizar_ano(registro.get('exercicio_decreto', '')),
            normalizar_numero(registro.get('decreto_numero', '')),
        )
        link_existente = texto_limpo(registro.get('link_decreto', ''))
        if not registro.get('assunto_decreto') and link_existente and not link_existente.lower().startswith(('http://', 'https://')):
            registro['assunto_decreto'] = link_existente

        assunto_mapa, link_mapa = mapa.get(chave, ('', ''))
        if assunto_mapa:
            registro['assunto_decreto'] = assunto_mapa
        if link_mapa.lower().startswith(('http://', 'https://')):
            registro['link_decreto'] = link_mapa
        elif not link_existente.lower().startswith(('http://', 'https://')):
            # Nome de arquivo não é URL: não transforma o texto em busca ampla do Drive.
            registro['link_decreto'] = ''

    for registro in registros:
        registro['_search_text'] = ' '.join(
            texto_limpo(registro.get(campo, '')) for campo in CAMPOS_BUSCA
        ).casefold()
    return registros


def carregar_dados():
    # A planilha oficial contém Exercicio e Decreto “G” em colunas distintas.
    # Ela é usada como referência quando o banco tem números vazios.
    try:
        dados_planilha = carregar_planilha()
    except Exception as e:
        print(f'Erro ao carregar do Drive: {e}')
        dados_planilha = []

    dados_banco = carregar_banco()
    if not dados_planilha:
        return aplicar_assuntos_e_links(dados_banco)
    if not dados_banco:
        return aplicar_assuntos_e_links(dados_planilha)

    por_ano_numero = {
        (linha['exercicio_decreto'], linha['decreto_numero']): i
        for i, linha in enumerate(dados_planilha)
        if linha['exercicio_decreto'] and linha['decreto_numero']
    }
    por_ano_data = {}
    for i, linha in enumerate(dados_planilha):
        chave = (linha['exercicio_decreto'], linha['data_elaboracao'])
        if all(chave):
            por_ano_data.setdefault(chave, []).append(i)

    chaves_removidas = set()
    for registro in dados_banco:
        ano = registro['exercicio_decreto']
        numero = registro['decreto_numero']
        chave_atual = (ano, numero)
        source_key = texto_limpo(registro.get('source_key', ''))
        chave_original = None
        if '|' in source_key:
            ano_original, numero_original = source_key.rsplit('|', 1)
            chave_original = (
                normalizar_ano(ano_original),
                normalizar_numero(numero_original),
            )

        indice = por_ano_numero.get(chave_atual) if ano and numero else None
        if chave_original and chave_original != chave_atual:
            indice_antigo = por_ano_numero.get(chave_original)
            if indice_antigo is not None:
                chaves_removidas.add(dados_planilha[indice_antigo]['_row_key'])
        elif chave_original and chave_original == chave_atual:
            indice = por_ano_numero.get(chave_original, indice)

        if indice is None and not source_key and ano and registro['data_elaboracao']:
            candidatos = por_ano_data.get((ano, registro['data_elaboracao']), [])
            for campo in ('orgao_elaboracao', 'link_decreto', 'processo_sei'):
                valor = registro.get(campo, '')
                if valor:
                    filtrados = [i for i in candidatos if dados_planilha[i].get(campo) == valor]
                    if filtrados:
                        candidatos = filtrados
            if len(candidatos) == 1:
                indice = candidatos[0]

        if indice is not None:
            destino = dados_planilha[indice]
            if source_key:
                for campo in (*COLUNAS_DADOS, 'assunto_decreto'):
                    destino[campo] = registro.get(campo, '')
                destino['exercicio_decreto'] = ano
                destino['decreto_numero'] = numero
                destino['source_key'] = source_key
            else:
                for campo in COLUNAS_DADOS:
                    # O ano e o número da planilha são a referência canônica.
                    if campo in ('exercicio_decreto', 'decreto_numero'):
                        continue
                    if registro.get(campo):
                        destino[campo] = registro[campo]
        elif ano and numero:
            # Mantém decretos cadastrados no banco que ainda não estão na planilha.
            registro['_row_key'] = uuid.uuid4().hex
            dados_planilha.append(registro)
            por_ano_numero[chave_atual] = len(dados_planilha) - 1

    if chaves_removidas:
        dados_planilha = [linha for linha in dados_planilha if linha['_row_key'] not in chaves_removidas]
    return aplicar_assuntos_e_links(dados_planilha)


